#!/usr/bin/env node
/**
 * Bundles every Supabase migration plus seed.sql into one paste-ready SQL file.
 *
 * Use it when the hosted project cannot be reached with the Supabase CLI: open
 * the dashboard SQL Editor, paste the generated file, and run it once.
 *
 * Usage:
 *   node scripts/bundle-supabase-setup.mjs [outputPath]
 *
 * The default output is supabase/hosted-setup.generated.sql, which is
 * git-ignored because it is a build artifact, not a source of truth.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = path.join(root, "supabase", "migrations");
const seedFile = path.join(root, "supabase", "seed.sql");
const outputPath = path.resolve(process.argv[2] ?? path.join(root, "supabase", "hosted-setup.generated.sql"));

const migrations = fs
  .readdirSync(migrationsDir)
  .filter((name) => name.endsWith(".sql"))
  .sort();

if (migrations.length === 0) {
  console.error("No migrations found in supabase/migrations.");
  process.exit(1);
}

const parts = [
  "-- HOPE Inc. ERP — full database setup, generated by scripts/bundle-supabase-setup.mjs",
  "-- Paste this entire file into the Supabase dashboard SQL Editor and run it once",
  "-- against a project that has no HOPE business tables yet.",
  "--",
  "-- It applies every migration in timestamp order, then supabase/seed.sql.",
  `-- Generated ${new Date().toISOString()} from ${migrations.length} migrations.`,
  "",
];

for (const name of migrations) {
  const sql = fs.readFileSync(path.join(migrationsDir, name), "utf8");
  parts.push(`-- =====================================================================`, `-- ${name}`, `-- =====================================================================`, sql.trimEnd(), "");
}

parts.push(
  "-- =====================================================================",
  "-- supabase/seed.sql",
  "-- =====================================================================",
  fs.readFileSync(seedFile, "utf8").trimEnd(),
  "",
);

fs.writeFileSync(outputPath, `${parts.join("\n")}\n`, "utf8");
const bytes = fs.statSync(outputPath).size;
console.log(`Wrote ${outputPath} (${(bytes / 1024).toFixed(1)} KiB, ${migrations.length} migrations + seed).`);
